        christian: "Christian",
        orthodox: "Orthodox",
        hebrew: "Jewish",
        islamic: "Islamic",
        hindu: "Hindu",
        de_facto: "De facto",
        protestant: "Protestant",
        sabian: "Sabian",
        yazidi: "Yazidi",
        albanian: "Albanian",
        armenian: "Armenian",
